export const STEPS = ["ticket", "plan", "plan_ok", "vm", "build", "pr", "byte", "approve", "learn"] as const;
export type Step = (typeof STEPS)[number];
export interface RunTags { agent: string; jira: string; id: string }

/** Env for one Agent SDK session. Its OTel data and its gateway calls carry the same tags. */
export function stepEnv(run: RunTags, step: Step): Record<string, string> {
  const tags = { agent: run.agent, jira: run.jira, run: run.id, step, "harness.version": HARNESS_VERSION };
  return {
    OTEL_RESOURCE_ATTRIBUTES: Object.entries(tags).map(([k, v]) => `${k}=${v}`).join(","),
    ANTHROPIC_CUSTOM_HEADERS: `x-ai-agents-step: ${step}\nx-ai-agents-harness: ${HARNESS_VERSION}`,
  };
}

const options: Options = {
