import { readFileSync } from "node:fs";

const pkg = JSON.parse(readFileSync(new URL("./package.json", import.meta.url), "utf8"));
export const HARNESS_VERSION = pkg.version;
export const STEPS = ["ticket", "plan", "plan_ok", "vm", "build", "pr", "byte", "approve", "learn"];

/** The environment for one session. Everything it sends carries the same tags. */
export const stepEnv = (run, step) => {
  if (!STEPS.includes(step)) throw new Error(`unknown step ${step}`);
  const tags = { agent: run.agent, jira: run.jira, run: run.id, step, "harness.version": HARNESS_VERSION };
  return {
    OTEL_RESOURCE_ATTRIBUTES: Object.entries(tags).map(([k, v]) => `${k}=${v}`).join(","),
    ANTHROPIC_CUSTOM_HEADERS: `x-ai-agents-step: ${step}\nx-ai-agents-harness: ${HARNESS_VERSION}`,
  };
};
EOF

cat > session.mjs <<'EOF'
// Stands in for one Agent SDK session: it needs the gateway, and it reports what its model calls cost.
import { MeterProvider, PeriodicExportingMetricReader } from "@opentelemetry/sdk-metrics";
import { OTLPMetricExporter } from "@opentelemetry/exporter-metrics-otlp-proto";
import { detectResources, envDetector } from "@opentelemetry/resources";

if (!process.env.GATEWAY_URL) throw new Error("no GATEWAY_URL: this session cannot reach the gateway");

const provider = new MeterProvider({
  resource: detectResources({ detectors: [envDetector] }), // reads OTEL_RESOURCE_ATTRIBUTES
  readers: [new PeriodicExportingMetricReader({ exporter: new OTLPMetricExporter() })],
});
const cost = provider.getMeter("lab").createCounter("claude_code.cost.usage", { unit: "USD" });
cost.add(Number(process.argv[2]), { model: "claude-opus-5-5" });
await provider.shutdown(); // sends the numbers before the process ends
EOF

cat > run.mjs <<'EOF'
// Stands in for the harness: one session per step, each with its own tags.
import { spawnSync } from "node:child_process";
import { stepEnv } from "./telemetry.mjs";

const run = { agent: "nova", jira: process.argv[2] ?? "RH-1234", id: "r-42" };
const costs = { ticket: 0.08, plan: 0.62, build: 2.95, pr: 0.31, learn: 0.14 };

let total = 0;
for (const [step, usd] of Object.entries(costs)) {
  const env = { ...process.env, ...stepEnv(run, step) };
  const done = spawnSync(process.execPath, ["session.mjs", String(usd)], { env, encoding: "utf8" });
  if (done.status === 0) total += usd;
  console.log(`${step.padEnd(6)} $${usd.toFixed(2)}  ${done.status === 0 ? "sent" : done.stderr.match(/Error: .*/)?.[0]}`);
}
console.log(`the gateway saw $${total.toFixed(2)} for ${run.jira}`);
EOF
